import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.HcBc_Mb9.js";const f=JSON.parse('{"title":"Delegation","description":"","frontmatter":{},"headers":[],"relativePath":"ai-fluency/02-delegation.md","filePath":"ai-fluency/02-delegation.md"}'),l={name:"ai-fluency/02-delegation.md"};function n(r,e,s,d,h,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to &quot;Delegation&quot;">​</a></h1><h2 id="what-you-ll-learn" tabindex="-1">What you&#39;ll learn <a class="header-anchor" href="#what-you-ll-learn" aria-label="Permalink to &quot;What you&#39;ll learn&quot;">​</a></h2><ul><li>Understand the Delegation competency and its three components: Problem Awareness, Platform Awareness, and Task Delegation</li><li>Recognize when and how to delegate tasks to AI effectively</li><li>Develop awareness of task, platform, and mode considerations when working with AI</li></ul><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Delegation is about making thoughtful decisions about what work to do yourself, what to do together with AI, or what to let AI handle independently, and how to distribute those tasks.</li><li>Problem Awareness means clearly understanding your goals and the nature of the work before involving AI. Platform Awareness involves understanding the capabilities and limitations of different AI systems.</li><li>Task Delegation is the process of thoughtfully distributing work between humans and AI to leverage the strengths of each. Effective delegation requires both domain expertise and an understanding of AI capabilities.</li><li>The goal isn&#39;t to automate everything, but to create the most effective human-AI partnership for any given task or goal.</li></ul><h2 id="delagation" tabindex="-1">Delagation <a class="header-anchor" href="#delagation" aria-label="Permalink to &quot;Delagation&quot;">​</a></h2><ul><li>Understanding the problem you&#39;re trying to solve</li><li>Understanding the capabilities of available AI tools</li><li>Breaking down complex work into smaller parts</li><li>Making strategic decisions about who does what</li><li>Choosing the right mode of interation</li></ul><h2 id="problem-awareness" tabindex="-1">Problem Awareness <a class="header-anchor" href="#problem-awareness" aria-label="Permalink to &quot;Problem Awareness&quot;">​</a></h2><p>The ability to clearly define your goals and understand what work is needed before involing AI tools</p><ul><li>What does &quot;success&quot; look like?</li><li>What kind of thinking and work is needed to get there?</li><li>AI fluency begins with and depends on your expertise?</li></ul><h2 id="platform-awareness" tabindex="-1">Platform Awareness <a class="header-anchor" href="#platform-awareness" aria-label="Permalink to &quot;Platform Awareness&quot;">​</a></h2><p>A working knowledge of available AI systems and their specific capabilities and limitations</p><ul><li>Understanding the unique strengths and limitations of available options</li><li>Which models perform best for the work you have in mind?</li><li>Which systems prioritize speed, or creativity, or depth, or accuracy?</li></ul><h2 id="task-delegation" tabindex="-1">Task Delegation <a class="header-anchor" href="#task-delegation" aria-label="Permalink to &quot;Task Delegation&quot;">​</a></h2><p>The strategic process of dividing work between humans and AI</p><ul><li>What could be usefully automated?</li><li>Where would augmentation create more value than working separately?</li><li>What should be done by a human alone?</li><li>What could be done by an agent on your behalf?</li></ul><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><div style="border-radius:18px;background:#d2cfe3;padding:28px;display:flex;gap:24px;align-items:center;"><div style="flex:0 0 140px;text-align:center;"><div style="width:120px;height:120px;margin:0 auto;border-radius:18px;background:#f5f3f7;display:flex;align-items:center;justify-content:center;"><span style="font-size:64px;line-height:1;color:#2d2a32;">✍️</span></div></div><div style="flex:1;"><h3 style="margin:0 0 10px 0;font-size:28px;color:#2d2a32;">Delegation Summary</h3><p style="margin:0 0 18px 0;font-size:18px;color:#2d2a32;line-height:1.6;"> Quick reference for the Delegation module. </p><a href="/anthropic-notes/ai-fluency/1.3_Delegation_Summary_16x9.pdf" style="display:inline-block;padding:12px 22px;border-radius:12px;background:#6f6a80;color:#ffffff;text-decoration:none;font-weight:600;">Download</a></div></div>',18)])])}const g=a(l,[["render",n]]);export{f as __pageData,g as default};
